svg.script:
var XPAD = 10; var FONTSIZE = 12; var FONTWIDTH = 0.6; var INVERTED = false; var SEARCHCOLOR = "rgb(230,0,230)";
"use strict";
var SVG, FRAMES, DETAILS, SEARCHBTN, UNZBTN, MATCHED, ICBTN;
var orig = [], searching = false, term = null, ignorecase = false;
var canvasW = 0;
function init() {
  SVG = document.getElementsByTagName("svg")[0];
  FRAMES = document.getElementById("frames").children;
  DETAILS = document.getElementById("details").firstChild;
  SEARCHBTN = document.getElementById("search");
  UNZBTN = document.getElementById("unzoom");
  MATCHED = document.getElementById("matched");
  ICBTN = document.getElementById("ignorecase");
  canvasW = SVG.width.baseVal.value;
  for (var i = 0; i < FRAMES.length; i++) {
    var r = rectOf(FRAMES[i]);
    orig.push({x:num(r,"x"), y:num(r,"y"), w:num(r,"width"), fill:r.getAttribute("fill")});
  }
  wire();
}
function num(el, a) { return parseFloat(el.getAttribute(a)); }
function rectOf(g) { return g.querySelector("rect"); }
function textOf(g) { return g.querySelector("text"); }
function nameOf(g) { return g.getAttribute("data-name") || ""; }
function indexOf(g) { return Array.prototype.indexOf.call(FRAMES,g); }
function groupOf(n) {
  while(n && n.parentNode && n.parentNode.id !== "frames") n=n.parentNode;
  return n && n.parentNode && n.parentNode.id === "frames" ? n : null;
}
function fitText(g,x,w) {
  var t=textOf(g); if(!t) return;
  var full=nameOf(g), room=w-6, chars=Math.floor(room/(FONTSIZE*FONTWIDTH));
  var points=Array.from(full);
  t.textContent=chars<2 ? "" : chars>=points.length ? full : points.slice(0,chars-2).join("")+"..";
}
function setGeom(g,x,w) {
  var r=rectOf(g),t=textOf(g); r.setAttribute("x",x); r.setAttribute("width",w);
  if(t) t.setAttribute("x",x+3); fitText(g,x,w);
}
function applyZoom(i) {
  if(i<0 || orig[i].w<=0) return;
  var base=orig[i], xmin=base.x, xmax=base.x+base.w;
  var ratio=(canvasW-2*XPAD)/base.w, fudge=0.0001;
  UNZBTN.classList.remove("hide");
  for(var k=0;k<FRAMES.length;k++) {
    var g=FRAMES[k],o=orig[k];
    g.classList.remove("hide"); g.classList.remove("parent");
    var ancestor=INVERTED ? o.y<base.y : o.y>base.y;
    if(ancestor) {
      if(o.x<=xmin+fudge && o.x+o.w+fudge>=xmax) {
        g.classList.add("parent"); setGeom(g,XPAD,canvasW-2*XPAD);
      } else g.classList.add("hide");
    } else if(o.x<xmin-fudge || o.x+o.w>xmax+fudge) g.classList.add("hide");
    else setGeom(g,(o.x-xmin)*ratio+XPAD,o.w*ratio);
  }
  if(term!==null) doSearch();
}
function resetZoom() {
  UNZBTN.classList.add("hide");
  for(var k=0;k<FRAMES.length;k++) {
    FRAMES[k].classList.remove("hide"); FRAMES[k].classList.remove("parent");
    setGeom(FRAMES[k],orig[k].x,orig[k].w);
  }
  if(term!==null) doSearch();
}
function clearHighlight() {
  for(var k=0;k<FRAMES.length;k++) rectOf(FRAMES[k]).setAttribute("fill",orig[k].fill);
}
function doSearch() {
  if(term===null) return;
  clearHighlight();
  searching=true; SEARCHBTN.classList.add("show"); SEARCHBTN.firstChild.nodeValue="Reset Search";
  MATCHED.classList.remove("hide");
  var re;
  try { re=new RegExp(term,ignorecase?"i":""); }
  catch(e) { MATCHED.firstChild.nodeValue="Invalid regular expression"; return; }
  var spans=[];
  for(var k=0;k<FRAMES.length;k++) {
    var g=FRAMES[k];
    if(g.classList.contains("hide") || g.classList.contains("parent")) continue;
    if(re.test(nameOf(g))) {
      var r=rectOf(g), x=num(r,"x"), right=x+num(r,"width");
      rectOf(g).setAttribute("fill",SEARCHCOLOR);
      spans.push({x:Math.max(XPAD,x),right:Math.min(canvasW-XPAD,right)});
    }
  }
  spans.sort(function(a,b){return a.x-b.x || b.right-a.right;});
  var count=0,end=XPAD;
  for(var j=0;j<spans.length;j++) {
    var s=spans[j];
    if(s.right>end) { count+=s.right-Math.max(end,s.x); end=s.right; }
  }
  var pct=Math.max(0,Math.min(100,100*count/(canvasW-2*XPAD)));
  MATCHED.firstChild.nodeValue="Matched: "+(pct===100?100:pct.toFixed(1))+"%";
}
function resetSearch() {
  searching=false; term=null; clearHighlight(); SEARCHBTN.classList.remove("show");
  SEARCHBTN.firstChild.nodeValue="Search"; MATCHED.classList.add("hide"); MATCHED.firstChild.nodeValue=" ";
}
function searchPrompt() {
  if(searching) {resetSearch();return;}
  var t=prompt("Enter a regular expression; Ctrl-I toggles case sensitivity","");
  if(t===null) return; term=t;doSearch();
}
function toggleIgnoreCase() {
  ignorecase=!ignorecase; ICBTN.classList.toggle("show",ignorecase);
  if(term!==null) doSearch();
}
function wire() {
  window.addEventListener("click",function(e){
    if(e.target.id==="unzoom") {resetZoom();return;}
    if(e.target.id==="search") {searchPrompt();return;}
    if(e.target.id==="ignorecase") {toggleIgnoreCase();return;}
    var g=groupOf(e.target);if(g) applyZoom(indexOf(g));
  });
  window.addEventListener("mouseover",function(e){var g=groupOf(e.target);if(g) DETAILS.nodeValue="Function: "+g.querySelector("title").textContent;});
  window.addEventListener("mouseout",function(e){if(groupOf(e.target)) DETAILS.nodeValue=" ";});
  window.addEventListener("keydown",function(e){
    if(e.keyCode===114 || (e.ctrlKey && e.keyCode===70)){e.preventDefault();searchPrompt();}
    else if(e.ctrlKey && e.keyCode===73){e.preventDefault();toggleIgnoreCase();}
  });
}
